-- From 20251226150000_add_novena_sao_jose.sql
-- Migration: Add Novena a São José
-- Description: Inserts the full content of the "Novena a São José" including common prayers and daily specific meditations.

DO $$
DECLARE
  v_novena_id uuid;
  v_day_id uuid;
  v_day_number integer;
  
  -- Text variables for common prayers to avoid repetition in source
  v_sign_cross text := 'Pelo sinal da Santa Cruz livrai-nos Deus, Nosso Senhor, dos nossos inimigos.';
  
  v_veni_creator text := 'Vinde, Espírito Santo, enchei os corações dos vossos fiéis e acendei neles o fogo do Vosso amor. Enviai o Vosso Espírito, e tudo será criado, e renovareis a face da terra. Oremos: ó Deus, que instruístes o coração dos vossos fiéis com a luz do Espírito Santo, fazei que apreciemos retamente todas as coisas, segundo o mesmo Espírito, e gozemos sempre da sua consolação. Por Cristo Senhor nosso. Amém!';
  
  v_prayer_initial text := 'Deus e Senhor meu, uno e trino, Pai, Filho e Espírito Santo, creio que estou em Vossa soberana presença agora, quando pretendo consagrar a São José esta novena. Adoro-vos com todo o meu coração, porque sois infinitamente bom e digno de ser amado sobre todas as coisas. Adoro-vos com toda a intensidade de que sou capaz e arrependo-me dos muitos pecados que fiz contra a Vossa Divina Majestade. Quero, nesta novena, aprender as virtudes que, com tanta perfeição, praticou o glorioso Patriarca São José, e alcançar, por sua intercessão, as graças de que tanto preciso.
Senhor, quem sou eu para atrever-me a comparecer diante de Vossa presença? Conheço a deficiência de meus méritos e a multidão de meus pecados, pelos quais não mereço ser ouvido em minhas orações; o que não mereço, merece-o São José, Pai nutrício de Jesus; o que eu não posso, ele pode. Venho, por isso, com total confiança, implorar a divina clemência, não fiando em minha fraqueza, mas no poder e valimento de São José.';

  v_prayer_virgin text := 'Virgem Imaculada, esposa castíssima de São José, assisti-me nestes momentos que dedico ao culto de vosso glorioso esposo. Sem auxílio, como eu poderia honrar dignamente o varão justo a quem dedicastes trinta anos de vida? Nem sei, nem posso honrá-lo como ele merece; por isso venho para que completeis o que me falta, e façais por ele o que não sei fazer. Ajudai-me, Senhora, nas minhas orações, para que sejam favoravelmente despachadas, pela intercessão e valimento de vosso Santo Esposo. Amém.';
  
  v_prayer_joseph text := 'Ó meu querido São José, ofereço-vos esta novena, com muito fervor e reverência e me consagro a vós, que merecestes o respeito e os favores de Jesus e de Maria, dedicados ao vosso serviço. Desejo obsequiar-vos dignamente, porque preciso ardentemente conseguir, por vossa intercessão, minha salvação eterna e as graças particulares que, rezando esta novena, desejo alcançar. Não olheis minhas faltas, mas a vossa grande misericórdia e o muito amor que professais.
O meu amável protetor, em vós ponho a confiança, atendei-me bondosamente. Amém.';

  v_prayer_final_all text := 'Lembrai-vos, ó puríssimo Esposo da Virgem Maria, doce protetor São José, que jamais se ouviu dizer que alguém que tivesse invocado proteção, implorado socorro e não fosse por vós consolado.
Com grande confiança, venho à vossa presença, recomendar-me fervorosamente a vós. Não desprezeis a súplica, ó Pai adotivo do Redentor, e dignai-vos acolhê-la piedosamente. Amém.
José, Filho de Davi, não temais receber Maria como Esposa Santíssima em vossa companhia, porque o que ela leva em suas puríssimas entranhas é por obra do Espírito Santo, José Santíssimo, rogai por nós para que sejamos dignos das promessas de Cristo. Amém.
Oremos: O Jesus, que por uma inefável providência, dignastes escolher o bem-aventurado José para esposo de Vossa Mãe Santíssima, concedei-nos que, aquele mesmo que veneramos como protetor, mereçamos tê-lo no Céu por intercessor. Vós que viveis e reinais com o Pai e o Espírito Santo por todos os séculos dos séculos. Amém.';

BEGIN
  -- 1. Create the Novena
  INSERT INTO public.novenas (slug, title, title_pt, description, description_pt, duration, is_active)
  VALUES (
    'novena-a-sao-jose',
    'Novena to St. Joseph',
    'Novena a São José',
    'Pray for protection and intercession from the Patron of the Universal Church.',
    'Poderosa novena para alcançar graças impossíveis e pedir a intercessão do Patrono da Igreja Universal.',
    9,
    true
  )
  RETURNING id INTO v_novena_id;

  -- 2. Loop through 9 Days
  FOR v_day_number IN 1..9 LOOP
    
    -- Insert Day
    INSERT INTO public.novena_days (novena_id, day_number, title, title_pt)
    VALUES (v_novena_id, v_day_number, 'Day ' || v_day_number, v_day_number || 'º Dia')
    RETURNING id INTO v_day_id;

    -- COMMON INTRO BLOCKS
    INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
    (v_day_id, 'prayer', v_sign_cross, v_sign_cross, 10),
    (v_day_id, 'prayer', v_veni_creator, v_veni_creator, 20),
    (v_day_id, 'paragraph', 'Orações para todos os dias', 'Orações para todos os dias', 30),
    (v_day_id, 'prayer', v_prayer_initial, v_prayer_initial, 40),
    (v_day_id, 'prayer', v_prayer_virgin, v_prayer_virgin, 50),
    (v_day_id, 'prayer', v_prayer_joseph, v_prayer_joseph, 60);

    -- SPECIFIC DAILY PRAYER (Depending on Day Number)
    IF v_day_number = 1 THEN
      INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
      (v_day_id, 'prayer', 
       'Specific Prayer Day 1', 
       'Dou graças à Santíssima Trindade, santíssimo José, pelos muitos privilégios, méritos e virtudes que vos enriqueceu e principalmente, pelo grande singularíssimo a poucos concedido, de ter sido santificado no ventre de vossa mãe e confirmado em graça.
Que alegria para vosso coração ver-vos livre do pecado, que é a única coisa que desagrada a Deus Filho, que vos chamava de Pai! Que graças destes à Trindade Beatífica por esse tão assinalado privilégio!
Eu vos felicito com meu coração, pela inocência incomparável que tivestes desde antes de nascer e pela graça e amizade particular com que o mesmo Deus vos distinguiu.
Por esse privilégio e pela grande alegria que Ele vos causou, suplico, ó meu querido Pai, que me alcanceis de Deus ódio ao pecado, amor às virtudes e a minha salvação eterna.
E como creio que a graça que desejo conseguir nesta novena, será benéfica à minha salvação, tenho inteira confiança de que a alcançarei por vossa poderosíssima intercessão e se minha oração não for bem dirigida, endireitai-a e rogai ao boníssimo Deus por mim. Amém.', 
       70);
    ELSIF v_day_number = 2 THEN
       INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
      (v_day_id, 'prayer', 
       'Specific Prayer Day 2', 
       'Que felicidade a vossa, glorioso protetor, serdes escolhido milagrosamente para esposo da Imaculada Maria! Alegro-me convosco pela satisfação imensa que experimentastes naquele dia feliz, quando associastes vossa sorte à da Mãe de Jesus Cristo.
Que admiração teriam os santos anjos, por serdes o sustentáculo da Mãe do Verbo Encarnado, e por esse mesmo motivo também protetor do Filho de Deus!
Uno meus louvores aos que, nesse dia, vos dariam os anjos do Céu e, de todo o meu coração vos felicito por ter sido dado de presente à Rainha dos Anjos, e pelo zelo com que se dedicou ao vosso serviço.

Que transbordante felicidade! Que maravilha ter por companheira aquela que trouxe o Filho de Deus em seu seio sagrado! Que felicidade ter, para vosso consolo, nas dificuldades a Consoladora dos aflitos, como conselheira a sapientíssima Mãe de Jesus Cristo e para modelo nas virtudes aquela que é o espelho sem mancha da Majestade divina e a imagem da bondade de Deus!

Por esse favor e felicidade tão grande, peço poderosíssimo São José, a amizade e a graça de Deus e a proteção e amparo constantes de Maria Santíssima.

Interponde ao mesmo tempo vosso valimento com Jesus e com a santíssima esposa, para alcançar as graças particulares que com esta novena pretendo conseguir.', 
       70);
    ELSIF v_day_number = 3 THEN
       INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
      (v_day_id, 'prayer', 
       'Specific Prayer Day 3', 
       'Que pena tão amarga devíeis ter sentido no coração, José Gloriosíssimo, quando em humildade julgastes dever separar-vos da esposa Maria, que tanto amáveis e que correspondia a vosso amor com amor puro e sincero.

Confraternizo convosco por aqueles momentos de sofrimento e por essa amarga provação que o Senhor permitiu!

Por caridade, ficastes ao lado da Mãe do Unigênito Filho de Deus. Maria vos pertenceu e amou sempre unida ao Amor de Deus.

Em Seu infinito poder, Deus fez nela maravilhas de Seu divino Amor. Fostes a maior testemunha das grandiosidades operadas em Maria. Maria é o jardim, o depositário desse eterno tesouro.

São José, aceitai sinceras felicitações pela parte ativa que Deus vos concedeu no mistério da Encarnação e pela sujeição de Jesus e de Sua santíssima Mãe às vossas ordens.

Por essa grande alegria e também pelos méritos da tristeza que a precedeu, suplico-vos, Pai querido, que alcanceis de Deus o conhecimento de Jesus Cristo e a graça de conservar uma fé tão viva em todos os seus mistérios que esteja pronto para antes morrer que duvidar deles; alcançai-me, outrossim, a graça que nesta novena pretendo conseguir, se for para maior glória de Deus e bem de minha alma. Amém.', 
       70);
    ELSIF v_day_number = 4 THEN
       INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
      (v_day_id, 'prayer', 
       'Specific Prayer Day 4', 
       'Esposo castíssimo da Mãe do Unigênito Filho de Deus, uno-me a vós na tristeza que experimentastes em Belém, quando, lá chegando, depois de penosa viagem, vistes a venerada esposa Maria e O Salvador do mundo, que ela levava em suas entranhas, desconhecidos e repelidos nas casas e pousadas. Ó meu querido São José, como conhecestes, então, que o mundo não é amigo de Cristo e que é impossível servir juntamente dois senhores tão inimigos e contrários!
Dai-me Jesus, que tanta alegria vos causou no nascimento. As vozes dos anjos, dizendo "Paz na Terra aos homens de boa vontade", são principalmente dirigidas a vós.
Aceitai louvores pelo muito amor que Jesus vos manifestou, escolhendo-vos para Pai nutrício e para poderoso defensor e amparo.
Permiti-me, gloriosíssimo e poderosíssimo Santo, chegar até onde estais, perto de Jesus, contemplar a Santidade divina e o esplendor.
Pedi a Jesus que me dê as graças recebidas pelos pastores e reis, que foram adorá-lo no presépio; pedi, também, as graças que desejo conseguir nesta novena, se forem para maior glória de Deus e salvação de minha alma. Amém.', 
       70);
    ELSIF v_day_number = 5 THEN
       INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
      (v_day_id, 'prayer', 
       'Specific Prayer Day 5', 
       'Que grande dor sofrestes, querido São José, quando vistes derramar-se o Preciosíssimo Sangue de Cristo na circuncisão!
Por que teria esse infante divino de sofrer assim, poucos dias depois de ter nascido? Sendo Jesus a perfeição em pessoa, certamente que esse sofrimento foi pelos nossos pecados.
São José, dai-me conhecer o preço do Sangue de Jesus, para que nunca deixe de perder a menor gota e que esse sangue, caindo abundantemente sobre minha alma, lave e purifique-me inteiramente.
Permiti, São José, que para conseguir graça tão importante, me aproxime mais de vós para ouvir atento e obedecer às bênçãos e às graças que dele emanam e, por bondade divina, passam por vossas sagradas mãos.
Vossas mãos sagradas ampararam Jesus, o Salvador do mundo, que tira os pecados dos homens!
São José, que alegria a vossa, quando destes ao Salvador o nome de Jesus, sabendo que esse nome é a própria felicidade, é a chave que abre a porta do Céu!
Adorador de Cristo, permiti que Jesus seja para mim meu Salvador, nesta vida e na eterna.
Pelo nome adorável, Jesus, peço-vos também as graças que desejo alcançar nesta novena, se forem para maior glória de Deus e para o bem de minha alma. Amém.', 
       70);
    ELSIF v_day_number = 6 THEN
       INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
      (v_day_id, 'prayer', 
       'Specific Prayer Day 6', 
       'Ó meu boníssimo São José, protetor dos desvalidos! Por aquela alegria que experimentou o vosso coração, ouvindo os louvores que os doutores da lei faziam a Cristo Menino, peço que não me esqueçais.
Fazei que Jesus, meu Salvador, seja sempre para mim ocasião de ressurreição. Confraternizo-me convosco, pacientíssimo José, pela ferida que em vosso coração fizeram as palavras de São Simeão, anunciando a Maria que uma espada de dor havia de atravessar seu delicadíssimo e amorosíssimo coração.
Em tão tremenda ocasião para Maria, vós nem poderíeis remediar essas dores, nem ao menos ser testemunha de tão terrível padecer, para consolar a esposa com a vossa presença humana na Paixão de Cristo!
Eu sim, com minha vida e bons costumes, preciso consolar Maria, porque sou culpado, por meus pecados, na morte de Jesus e nas dores de Maria, e quero reparar esses pecados.
Ajudai, José poderosíssimo, minha pobreza espiritual e poucas forças, alcançando de Nosso Senhor a graça de nunca ser, por própria culpa, causa de sofrimento de Jesus e das dores de Maria.
Alcançai-me também a graça que desejo conseguir rezando esta novena, se for para maior glória de Deus e salvação de minha alma. Amém.', 
       70);
    ELSIF v_day_number = 7 THEN
       INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
      (v_day_id, 'prayer', 
       'Specific Prayer Day 7', 
       'São José, permiti que, em espírito, acompanhe na viagem ao Egito, para admirar os sacrifícios e imitar vossas virtudes. Tudo fizestes para defender Jesus de tantos perigos e, sobretudo, da morte. Que tão grande dor foi para o vosso coração amante ver sofrer Jesus e Maria!

Quanta sede devem ter sofrido no deserto os três peregrinos santíssimos!
Peço humildemente que tireis de mim a sede dos prazeres mundanos e dai-me a fome e sede das virtudes, principalmente a humildade, a paciência e a mortificação que minha alma deseja ardentemente possuir.

Entristeçam-me as coisas que vos entristecem, amável São José, e que eu saiba alegrar-me com as que vos causam alegria. Experimente minha alma, conservando-se na graça de Deus, a mesma alegria que experimentou vosso delicado coração quando, afinal, depois dos transtornos duma perigosa viagem por ermos desertos, vistes salvos Jesus e Maria, a amantíssima esposa, e seguros no novo lar.

Assim, como vos alegrastes com a queda dos ídolos, das afeições desregradas e das paixões desordenadas, eu me alegro de modo que, em tudo e por tudo, agrade Jesus, à santíssima Mãe e a também vós, meu amável José, que tanto gozais na glória de Deus.

Alcançai-me, também, a graça que desejo conseguir rezando esta novena, se for para maior glória de Deus e salvação de minha alma. Amém.', 
       70);
    ELSIF v_day_number = 8 THEN
       INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
      (v_day_id, 'prayer', 
       'Specific Prayer Day 8', 
       'Confraternizo-me convosco, terníssimo Jose, por causa das privações a que vistes sujeita a amada família, na terra da peregrinação.
Uno minhas lágrimas às que derramastes pela dureza do exílio e por tudo que vos faltou, a Maria e a Jesus no Egito.
Por vossa família, que é a família de Deus, tão paciente, eu ofereço qualquer pequena e insignificante mortificação.
Ó meu querido São José, pela alegria imensa que inundou vosso coração quando Jesus falou o doce nome de Pai, e pela sujeição com que pela primeira vez vos prestou homenagem de obediência, suplico que me ensineis obedecer aos superiores e sofrer, com paciência e resignação, as provas que a Divina Providência se dignar enviar-me, para purificar-me de meus pecados ou para aumentar meus méritos.
Alcançai-me, também, pela alegria com que voltastes do exílio para morar em Nazaré, a graça que com tanta humildade vos peço nesta novena, se não houver prejuízo de minha salvação. Amém.', 
       70);
    ELSIF v_day_number = 9 THEN
       INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
      (v_day_id, 'prayer', 
       'Specific Prayer Day 9', 
       'O José, chamado por Jesus pelo nome de Pai, que dor e tormento indizível seria para vosso coração amorosíssimo ter perdido Jesus, com o qual estavam todas as afeições de vossa vida! Que grande aflição sentistes por não ter encontrado o menino Jesus entre parentes e conhecidos e por ninguém ter dado notícias d''Ele.
Onde estaria Jesus? Como poderíeis viver sem Ele, que era vossa alegria de viver? Perdestes Jesus sem própria culpa, mas eu O perdi muitas vezes por própria culpa, por causa de malícia e de meus pecados.
Fazei-me conhecer Jesus e procurá-lo com perseverança, ensinai-me obedecer, ensinai-me adorá-lo, custe o que custar. Consegui-me a graça de que, de hoje em diante, nunca mais eu O perca pelo pecado e que, se por infelicidade eu venha a perdê-lo, nunca tenha sossego até que O encontre novamente, pela divina graça.
Peço-vos essa graça, pela alegria inefável que experimentastes encontrando Jesus, no Templo, ensinando, como Mestre Divino, os doutores da lei e causando-lhes encanto e admiração com perguntas e respostas. Intercedei para que eu esteja sempre em união com Jesus e a Santa Igreja.
Consegui que Jesus esteja sempre em meu coração, com a divina Caridade e que, no futuro, possa gozar de Sua visão e amizade no Céu, para sempre.
Alcançai-me, também, as graças que pedi nestes dias, durante esta novena. Tenho confiança de que tudo que pedi, irei receber do Amor de Deus, por vosso intermédio. De agora em diante, com a graça divina, serei divulgador do poder que o Misericordiosíssimo Deus vos concede. Amém.', 
       70);
    END IF;

    -- COMMON OUTRO BLOCKS & ACTIONS
    INSERT INTO public.day_content_blocks (novena_day_id, block_type, content, content_pt, sort_order) VALUES
    (v_day_id, 'prayer', v_prayer_final_all, v_prayer_final_all, 80),
    (v_day_id, 'intention', 'Pedir a graça que se deseja alcançar.', 'Pedir a graça que se deseja alcançar.', 90);

    INSERT INTO public.day_checklist_items (novena_day_id, label, label_pt, sort_order) VALUES
    (v_day_id, 'Rezar: sete Pai-Nossos, sete Ave-Marias e sete Glórias, em honra das alegrias e dores do glorioso Patriarca.', 'Rezar: sete Pai-Nossos, sete Ave-Marias e sete Glórias, em honra das alegrias e dores do glorioso Patriarca.', 1);

  END LOOP;
END $$;



-- From 20251226164500_add_novena_sao_rafael.sql
-- Create Novena of São Rafael Arcanjo

DO $$ 
DECLARE
    v_novena_id uuid;
    v_day_id uuid;
    v_day_num integer;
BEGIN
    -- 1. Insert Novena
    INSERT INTO novenas (title, description, slug, duration)
    VALUES (
        'Novena a São Rafael Arcanjo', 
        'Poderosa novena para cura de doenças e para encontrar um bom matrimônio, pedindo a intercessão do Arcanjo que guiou Tobias.', 
        'sao-rafael-arcanjo', 
        9
    )
    RETURNING id INTO v_novena_id;

    -- 2. Loop for 9 Days
    FOR v_day_num IN 1..9 LOOP
        -- Insert Day
        INSERT INTO novena_days (novena_id, day_number, title)
        VALUES (v_novena_id, v_day_num, 'Dia ' || v_day_num)
        RETURNING id INTO v_day_id;

        -- Insert Content Blocks

        -- Block 1: Intro / Bible Reading Title
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 0, 'paragraph', 'Inicia-se com a leitura do livro de Tobias 9:1-7:');

        -- Block 2: Bible Text (Tobias 9:1-7)
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 1, 'quote', 'Tobias chamou então a si o anjo, que ele julgava ser um homem, e disse-lhe: "Azarias, meu irmão, peço-te que me ouças. Ainda que eu me fizesse teu escravo, não seria isso uma retribuição digna por teus cuidados. Não obstante, vou pedir-te ainda que tomes contigo cavalos e servos e vás à casa de Gabael, em Ragés, na Média. Devolve-lhe o seu recibo e recebe o dinheiro. Convida-o também para o meu casamento. Bem sabes que meu pai conta os dias; se eu tardar um dia mais, ele sofrerá com isso. Vês, por outro lado, como Raguel insistiu em que eu me demorasse aqui e não lho posso recusar". Rafael tomou então quatro servos de Raguel, dois camelos e partiu para Ragés, na Média. Encontrando Gabael, entregou-lhe o recibo e recebeu dele todo o dinheiro. Contou-lhe toda a aventura de Tobias e fê-lo vir consigo às núpcias.');

        -- Block 3: Opening Prayer
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 2, 'prayer', 'Ó Deus, que em sua inefável bondade tem enviado o abençoado Rafael como condutor e guia de Vossos devotos em sua jornada, nós humildemente imploramos a Vós que nós possamos ser conduzidos por ele no caminho de nossa salvação e experimentar sua ajuda na cura das moléstias de nossa alma. Tudo através de Jesus Cristo Nosso Senhor. Amém.');

        -- Block 4: Daily Prayer
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 3, 'prayer', 'Oh! Glorioso Arcanjo São Rafael, que estais presente ante o trono do Altíssimo. Eu, vosso indigno devoto, me humilho em vossa presença. Conhecendo por uma parte minha indignidade, e por outra vossa ardente caridade, vos suplico do íntimo do coração, que digneis escutar os meus humildes rogos e apresente-os ante o Senhor para obter por vossa mediação os favores que solicito nesta novena. Mas se minha súplica não há de contribuir para maior glória de Deus e salvação da minha alma, rogo-vos, oh! Meu Celestial protetor, mostrai a graça que me há de conduzir com mais segurança à eterna salvação. Não olheis tanto para os meus desejos, quanto ao bem de minha alma. Cheio de inteira confiança em Vós; espero alcançar o que solicito pelos méritos de Nosso Senhor Jesus Cristo, que vive e reina com o Pai e o Espírito Santo pelos séculos dos séculos. Amém.');

        -- Block 5: Intention Placeholder
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 4, 'intention', 'Coloque suas intenções aqui...');

        -- Block 6: Invocation
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 5, 'prayer', 'Invocação:\n\nOh! Glorioso Arcanjo São Rafael, lembra-te de seus devotos, em todas as partes e sempre peça por nós, ao Filho de Deus.');

        -- Block 7: Litany (Ladainha)
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 6, 'prayer', 'Ladainha a São Rafael Arcanjo:\n\nSenhor, tende piedade de nós\nCristo, tende piedade de nós\nCristo, graciosamente nos escutai\nDeus Pai, tende piedade de nós\nSenhor, tende piedade de nós\nDeus Filho, redentor do mundo, tende piedade de nós\nDeus Espirito Santo, tende piedade de nós\nSanta Trindade e Um só Deus, tende piedade de nós\nSanta Maria, rainha dos anjos, rogai por nós.\nSão Rafael, rogai por nós\nSão Rafael, cheio da misericórdia de Deus, rogai por nós\nSão Rafael, perfeito adorador do Divino Mestre, rogai por nós\nSão Rafael, terror dos demônios, rogai por nós\nSão Rafael, exterminador dos vícios, rogai por nós\nSão Rafael, saúde dos doentes, rogai por nós\nSão Rafael, refugio em nossas necessidades, rogai por nós\nSão Rafael, consolador dos prisioneiros, rogai por nós\nSão Rafael, alegria dos tristes, rogai por nós\nSão Rafael, cheio de zelo para a salvação de nossas almas, rogai por nós\nSão Rafael, cujo nome significa cura, rogai por nós\nSão Rafael, amante da castidade, rogai por nós\nSão Rafael, acoite dos demônios, rogai por nós\nSão Rafael, nosso protetor na peste, na fome, na guerra, rogai por nós\nSão Rafael, anjo da paz e da prosperidade, rogai por nós\nSão Rafael, repleto da graça da cura, rogai por nós\nSão Rafael, guia seguro no caminho da virtude e santificação, rogai por nós\nSão Rafael, socorro de todos que imploram a sua ajuda, rogai por nós\nSão Rafael, que guiou e consolou Tobias em sua jornada, rogai por nós\nSão Rafael, aquele que as Escrituras saúdam, como “Rafael o santo anjo do Senhor foi enviado para curar”, rogai por nós\nSão Rafael, nosso advogado, nos salve\n\nCordeiro de Deus que tirastes os pecados do mundo, tende piedade de nós,\nCristo, escutai nossas preces\nTende misericórdia de nós.\nSão Rafael, rogai por nós a Nosso Senhor Jesus Cristo,\nAgora e na hora de nossa morte. Amém');

        -- Block 8: Final Prayer
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 7, 'prayer', 'Oração Final:\n\nGlorioso Arcanjo São Rafael, celeste mensageiro destinado por Deus para nos servir de guia na peregrinação desta vida, para nos defender contra as ciladas do demônio e para curar as enfermidades da nossa alma e do nosso corpo. Nós invocamos vossa poderosa intercessão, seguros de que alcançareis por nós e nossas famílias aquelas graças singulares que dispensastes na santa casa de Tobias.\n\nBem sabeis piedoso Arcanjo, que nossa viagem do tempo à eternidade, está cercada de perigos, e que o demônio, como leão rugindo, nos persegue para causar profundas feridas em nossas almas, até apagar nelas, se for possível, a luz salvadora da fé. Vinde, pois, em nosso auxílio, e dignais ser nosso inseparável companheiro. Dirigi nossos passos ao caminho dos mandamentos divinos fazendo que nossos olhos estejam sempre abertos ao sol da verdade; procurando os remédios mais eficazes para curar e encher de fervor nosso espírito. Ensina-nos, oh! Poderoso arcanjo, a vencer a Satanás com as armas poderosas da oração, da vigilância e da mortificação dos nossos sentidos.\n\nConsolide em nossas famílias o reinado da fé, a prática constante da piedade, o espírito de união e o exercício da santa caridade em favor dos pobres e dos nossos queridos mortos, a fim de que eles recebam do céu abundantes bênçãos que, por mediação vossa derramou Deus sobre o lar de Tobias.\n\nNão nos abandoneis, pois, oh! Santo Arcanjo! Vigiai sempre ao nosso lado para que nossos passos sejam sustentados por vós, todas as vezes que sintamos desfalecidos na penosa e difícil jornada da vida. Nosso Senhor, Deus Todo-poderoso, que estais nos céus, e que é também o vosso, nos há confiado a vossa terna solicitude para que seja nosso guia neste desterro, nosso consultor nas dúvidas e nosso médico nas enfermidades. Coroais vossa obra de amigo fiel e condutor seguro, acompanhando nossas almas até as deixar nos braços de seu criador para amar-lhe e bendizer-lhe com vós eternamente. Assim seja.');

        -- Block 9: Footer
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 8, 'paragraph', 'Bendito e adorado seja o Santíssimo Sacramento do Altar e a Puríssima e Imaculada Conceição de Maria Santíssima, Senhora Nossa, concebida sem mancha de pecado original desde o primeiro instante de seu ser natural. Amém.');


        -- Insert Checklist Items

        -- Item 1: 9 Glorias
        INSERT INTO day_checklist_items (novena_day_id, label, repetition_count)
        VALUES (v_day_id, 'Rezar 9 vezes o Glória ao Pai, em honra dos nove coros angélicos', 9);

        -- Item 2: Terminate
        INSERT INTO day_checklist_items (novena_day_id, label, repetition_count)
        VALUES (v_day_id, 'Finalizar com a Oração Final', 1);

    END LOOP;
END $$;



-- From 20251226174500_add_novena_sao_tomas.sql
-- Create Novena of Santo Tomás de Aquino

DO $$ 
DECLARE
    v_novena_id uuid;
    v_day_id uuid;
    v_day_num integer;
    v_daily_meditation text;
BEGIN
    -- 1. Insert Novena
    INSERT INTO novenas (title, description, slug, duration)
    VALUES (
        'Novena a Santo Tomás de Aquino', 
        'Santo Tomás de Aquino, nascido em 1225 no castelo de Roccasecca, foi um dos maiores teólogos e filósofos da Igreja, reconhecido como Doctor Angelicus. Após estudos em Monte Cassino, Nápoles, Paris e Colônia, destacou-se como mestre de teologia, combinando profunda fé e humildade com um saber vasto e sólido. Autor da monumental Summa Theologica, suas obras influenciaram profundamente a teologia católica, sendo referência em dogmas e refutações de erros. Devoto e piedoso, compôs hinos como Tantum Ergo, que celebram o Santíssimo Sacramento. Canonizado em 1323, é padroeiro dos estudos superiores e exemplo de santidade e sabedoria.', 
        'sao-tomas-de-aquino', 
        9
    )
    RETURNING id INTO v_novena_id;

    -- 2. Loop for 9 Days
    FOR v_day_num IN 1..9 LOOP
        -- Insert Day
        INSERT INTO novena_days (novena_id, day_number, title)
        VALUES (v_novena_id, v_day_num, 'Dia ' || v_day_num)
        RETURNING id INTO v_day_id;

        -- Determine Daily Meditation Content
        CASE v_day_num
            WHEN 1 THEN
                v_daily_meditation := 'A humildade é uma virtude que restringe o apetite e o contém para não armazenar excessivamente objetos altos e excessivos. O humilde que, de acordo com São Isidoro, é inclinado à terra, considerando suas imperfeições e defeitos, está sempre arruinado e pequeno, e como o patriarca Abraão exclama em sua oração: “falarei ao Senhor meu Deus, não sendo mais que poeira e cinzas”.' || chr(10) || chr(10) || 'São Tomás de Aquino sempre praticou a humildade como a mais bela e necessária das virtudes. Ainda criança, ele era o encantamento de todos pela modéstia e humildade de seu caráter; quando era estudante, seus colegas, tendo em vista o silêncio muito humilde com o qual tentava encobrir os talentos que Deus o havia preenchido, recebeu o apelido de Boi Mudo e, mais tarde, doutor nas universidades de Paris e Roma, nunca se notou nele algum sinal de arrogância e vaidade e recusava vigorosamente as mais altas dignidades da Igreja sem sequer exercer a posição de prelado em um convento de sua ordem.';
            WHEN 2 THEN
                v_daily_meditation := 'Todos temos razões suficientes para nos humilharmos e nos reconhecermos em outros méritos e reconhecermos nos outros os méritos e excelências, de acordo com o apóstolo; “Vamos humildemente julgar os outros como nossos superiores”.' || chr(10) || chr(10) || 'Estava o doutor angélico tão persuadido da necessidade de ser humilde, o que pode ser dito que era seu esforço máximo e o norte de todos os seus atos. Sendo tão grande, ele nunca acreditou em sua grandeza e sempre pareceu pequeno e inferior aos outros.';
            WHEN 3 THEN
                v_daily_meditation := 'Após as virtudes teológicas que nos direcionam diretamente a Deus e a justiça que estabelece a ordem da razão, a virtude da humildade com que a alma se dispõe para todas as outras virtudes segue em dignidade e excelência. É por isso que a humildade deve ser comparada à fundação de um edifício, pois, removendo tudo o que a Deus desagrada, torna a alma apta a receber as graças divinas, porque sabe-se que Deus resiste aos orgulhosos e dá sua graça aos humildes.' || chr(10) || chr(10) || 'Todos os agradecimentos recebidos por São Tomás, eles tinham sua razão e começaram na humildade de sua alma. Seus olhos, no chão, indicavam o êxtase milagroso em que seu coração foi tomado; suas palavras sempre eram muito modestas e oportunas, preferindo o silêncio à tagarelice vã; ele nunca quis distinguir entre seus irmãos e sua vida era bela, a mais modesta na presença do Senhor.';
            WHEN 4 THEN
                v_daily_meditation := 'A sabedoria é um dos dons do Espírito Santo, com o qual a inteligência banhada pelas luzes celestes, é correta ao contemplar as coisas mais altas e, uma vez vistos esses motivos supremos, desce para julgar e correr sobre os outros objetos subordinados à razão.' || chr(10) || chr(10) || 'Santo Tomás foi o novo Salomão da Igreja por causa da sabedoria portentosa com que o céu o enriqueceu. E como o velho Salomão diz a Sagrada Escritura que sabia tudo, desde o cedro das montanhas ao musgo e o hissopo das paredes, pode-se dizer a Tomás de Aquino que nada escapou de sua inteligência soberana, da teologia às ciências físicas e da Sagrada Escritura à política e linguística.';
            WHEN 5 THEN
                v_daily_meditation := 'A sabedoria não é uma mera virtude técnica que figura todos os seus encantos na contemplação das maravilhas de Deus e na simples especulação dos mais altos princípios das coisas, mas, como diz o apóstolo, estende sua influência aos atos da vida regularizando os movimentos e organizando os fins das causas secundárias.' || chr(10) || chr(10) || 'Desde que Santo Tomas, quando garoto de cinco anos, discutiu com os monges do Monte Casino, perguntando-lhes sobre a existência e os atributos de Deus, até que ele foi condecorado pelas universidades mais famosas do mundo, ele explicou como professor soberano as questões mais abstrusas da razão e da natureza. A fé e a sabedoria em seu sentido mais belo eram os companheiros inseparáveis de sua vida e o norte luminoso de todas as suas operações.';
            WHEN 6 THEN
                v_daily_meditation := 'Visto que esse dom do Espírito Santo é uma virtude tão bela e excelente, não pode ser encontrado, como foi dito no dia anterior, com a mancha e a culpa da alma: mas onde a graça está assentada, vive a sabedoria, agora que Deus ama apenas aqueles que são adornados com sabedoria, e o amor de Deus implica a alma em graça e causa, ao contrário, a mesma graça e amizade divina.Cabazes de oferta' || chr(10) || chr(10) || 'Raramente a sabedoria brilhou tão pura e radiante quanto na testa de Santo Tomás. E não apenas ele parou na luz que encantou aqueles que o viram com seus raios, mas que em um incêndio de caridade ele atraiu a Deus aqueles que se ilustraram de perto com os esplendores daquele Sol. Ninguém falou com Santo Tomas que não era docemente amarrado com correntes de amor divino, ninguém o viu para não abençoar o céu, ninguém o ouviu em suas explicações luminosas do Mestre, que não acreditavam ter visto o dedo de Deus acendendo em sua inteligência a bela chama do gênio.';
            WHEN 7 THEN
                v_daily_meditation := 'Entre as virtudes cristãs, não há nada mais belo e resplandecente que a santa virgindade, através da qual, como ensina Santo Agostinho, a integridade da carne é consagrada e oferecida ao Senhor. Assim como se diz que uma planta é verde e fresca, quando a abundância de calor não agita ou murcha sua seiva, uma pessoa chamada virgem é dedicada a tudo de seu Deus. Ela está livre do calor das paixões e fogo de concupiscência; Portanto, Santo Ambrósio diz que, na razão da virgindade, está envolvido o conceito de limpeza absoluta e que a alma está livre da corrupção dos sentidos, sendo a essência dessa virtude celestial acompanhada de um propósito firme e perpétuo: abster-se da imundície da sensualidade.' || chr(10) || chr(10) || 'Santo Tomás foi um virgem muito puro a vida toda. Da luta titânica mantida em Roca-Seca, onde conquistou como soldado corajoso a bela palma da vitória e o cordão abençoado com o qual os anjos enrolavam seus lombos, a vida inteira do inacabado doutor dominicano era um contínuo idílio de inocência que eles mesmos os serafins adoraram.';
            WHEN 8 THEN
                v_daily_meditation := 'Basta saber que é virtude e ato meritório, portanto, entender não apenas a legalidade, mas pelo menos a conveniência da virgindade. Além disso, é sabido que, nos atos humanos, algo ilícito e cruel pode ser encontrado quando os poderes se opõem ou não seguem a opinião do motivo que é o regulador de todas as operações, ordenando-os para um fim pré-concebido como bom.' || chr(10) || chr(10) || 'Santo Tomás vivia tão separado da carne e de seus instintos que, mais do que um homem, ele parecia um anjo ocupado apenas em Deus e no aumento de sua honra. Nem a próstata de sua linhagem era suficiente para ofuscar seu coração, nem a delicadeza de seu corpo inocente, fazia parte para atenuar o rigor com o qual ele sempre tentava mortificar e manter suas paixões afastadas e os apetites por toda sua carne.';
            WHEN 9 THEN
                v_daily_meditation := 'Sem dúvida, é a virgindade mais bela e excelente do que o estado civil e uma das virtudes mais agradáveis aos olhos divinos. Dizer o contrário, afirmar que o casamento é em si mais perfeito que o estado celibatário, foi o erro de Jovinian tantas vezes repetido e vangloriado em tons às vezes satíricos e além de satiristas profanos e imorais.' || chr(10) || chr(10) || 'O doutor angélico estava tão apaixonado pelo estado religioso e tão apaixonado pela virgindade que se observa que os ferozes ataques promovidos pelo mundo, demônios e carne não foram suficientes para fazê-lo desistir de sua companhia. Religioso vestidos com um hábito muito branco, símbolo de inocência e sinceridade, era São Tomás de Aquino e por ter abraçado a vida pobre, mortificada e oculta em Jesus, o perfume de sua pureza imaculada e o brilho de sua ciência celestial descobriram seus tesouros e deram nome e fama sem segundo santo.';
        END CASE;

        -- Insert Content Blocks
        
        -- Block 0: Intro Prayer
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 0, 'prayer', 'Oração Inicial:\n\nÀ vós, meu Deus, fonte de misericórdia, eu me aproximo, pecador imundo, para que Vós Vos digneis a lavar minhas manchas. Ó sol da justiça, ilumine esse cego! Ó Doutor Eterno, cure este miserável! Ó Rei dos reis, vista este nu! Ó mediador entre Deus e os homens, reconcilie esse preso! Ó, Bom Pastor, seja bem-vindo a esta ovelha rebelde! Concedei, meu Deus, perdão a esse criminoso, indulgência a esse ímpio e a unção de Sua graça a essa vontade endurecida. Ó misericordioso Senhor, chame Seu fugitivo, atraia este resistente, levante aquele que caiu e uma vez ressuscitado, segure-o e guie seus passos. Não se esqueça, Senhor, a quem Vos esqueceu, não abandone aqueles que O abandonaram, não descarte aqueles que O rejeitaram e perdoe no céu aqueles que O ofenderam na terra. Amém.');

        -- Block 1: Prayer to Virgin
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 1, 'prayer', 'Oração à Santíssima Virgem:\n\nÓ abençoada e doce Virgem Maria, oceano de bondade, Filha do rei soberano, Rainha dos anjos e Mãe do Criador! Me jogo confiante no seio de sua misericórdia e ternura, confiando-lhe meu corpo, minha alma, meus pensamentos, meus desejos, meus afetos e minha vida inteira, para que, com sua ajuda, eu sempre ande em direção ao bem, de acordo com a vontade de seu amado Filho, Nosso Senhor Jesus Cristo. Amém');

        -- Block 2: Daily Meditation
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 2, 'paragraph', v_daily_meditation);

        -- Block 3: Final Prayer
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 3, 'prayer', 'Oração Final:\n\nGraças, Vos dou, Senhor meu Deus, e Pai das misericórdias, porque Vos dignastes a admitir, ao Seu pobre pecador e Seu indigno servo, a livre participação de Sua graça no segredo da oração. Peço-Lhe que esta comunicação da minha alma convosco não seja um castigo pelos meus defeitos, mas um penhor seguro do perdão das minhas ofensas, da melhor armadura da fé e do invulnerável escudo do meu coração. Conceda-me a remissão dos meus defeitos, o extermínio da concupiscência e sensualidade, o aumento da caridade, humildade, paciência, obediência e todas as virtudes; me defenda das armadilhas visíveis e invisíveis dos inimigos; Dá-me a calma inefável de meus apetites e todos os meus afetos, para que eu possa me juntar a Vós; melhor do que vossa é minha felicidade e descanso. Eu também imploro meu Deus, que depois de minha morte, Vós Vos digneis de me admitir na Páscoa celestial e no convite divino, onde Vós, em união do Filho e do Espírito Santo, Sois luz verdadeira, abundância perfeita, alegria eterna, alegria consumada e felicidade sem medida. Amém.');

        -- Block 4: Intention (Placeholder)
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 4, 'intention', 'Peça a graça especial que deseja alcançar por intercessão de Santo Tomás');

        -- Block 5: Checklist Marker
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 5, 'checklist', 'Checklist de Orações Finais');

        -- Block 6: Footer/Invocation
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 6, 'prayer', 'Ó Santo Tomás, glória e honra da Ordem dos Pregadores! Transporte-nos para a contemplação das coisas celestes, vós que fostes soberano mestre dos mistérios sagrados. Rogai por nós, Santo Tomás, para que sejamos dignos das promessas de Jesus Cristo.');


        -- Insert Checklist Items (Standard prayers mentioned in text)
        INSERT INTO day_checklist_items (novena_day_id, label, repetition_count)
        VALUES (v_day_id, 'Pai-Nosso', 1);

        INSERT INTO day_checklist_items (novena_day_id, label, repetition_count)
        VALUES (v_day_id, 'Ave-Maria', 1);

        INSERT INTO day_checklist_items (novena_day_id, label, repetition_count)
        VALUES (v_day_id, 'Glória', 1);

    END LOOP;
END $$;



-- From 20251226175500_add_novena_santo_agostinho.sql
-- Create Novena of Santo Agostinho

DO $$ 
DECLARE
    v_novena_id uuid;
    v_day_id uuid;
    v_day_num integer;
    v_quote text;
    v_meditation text;
BEGIN
    -- 1. Insert Novena
    INSERT INTO novenas (title, description, slug, duration)
    VALUES (
        'Novena a Santo Agostinho', 
        'Agostinho nasceu em Tagaste, na África do Norte, em 354. Tendo a princípio escutado docilmente sua mãe, Santa Mônica, em breve se deixou arrastar para as mais graves desordens... Recuperado pela graça e pelas lágrimas de sua mãe, tornou-se um dos maiores Santos e Doutores da Igreja. Padroeiro dos teólogos, sua vida é um testemunho ardente de que "nosso coração está inquieto enquanto não repousa em Deus".', 
        'santo-agostinho', 
        9
    )
    RETURNING id INTO v_novena_id;

    -- 2. Loop for 9 Days
    FOR v_day_num IN 1..9 LOOP
        -- Insert Day
        INSERT INTO novena_days (novena_id, day_number, title)
        VALUES (v_novena_id, v_day_num, 'Dia ' || v_day_num)
        RETURNING id INTO v_day_id;

        -- Determine Daily Content (Quote and Meditation)
        CASE v_day_num
            WHEN 1 THEN
                v_quote := '“Fizeste-nos para Vós, Senhor, e o nosso coração está inquieto, enquanto não repousar em Vós.”';
                v_meditation := 'Essa célebre frase, talvez a mais conhecida de Santo Agostinho, é a que abre seu principal livro, as Confissões. Toda a vida do santo Bispo de Hipona poderia ser resumida por ela. Depois de trinta anos vivendo uma vida de contínuas inquietações, experimentou a vida sensual em suas variadas formas, adentrou em seitas e filosofias, mas só encontrou a paz para a sua alma e o sossego para o seu coração ao conhecer o catolicismo e entregar a sua vida a Deus.' || chr(10) || chr(10) || 'O homem é um peregrino nesta Terra, e a única coisa que realmente pode saciar a sua sede é o encontro com Deus. Como o cervo que anseia pelas águas correntes, também a alma anseia por Deus.';
            WHEN 2 THEN
                v_quote := '“Ama, e faze o que queres! Se emudeces, emudece por amor; se gritas, grita por amor; se repreendes, repreende por amor; se perdoas, perdoa por amor.”';
                v_meditation := 'Apesar de ter sido um grande Doutor da Igreja, um intelectual de vasto conhecimento, São Agostinho nos ensina com simplicidade a amar a Deus e ao próximo com a vida, sem grandes filosofias. O amor é o princípio, o meio e o fim de nossa existência. É por amor que devemos fazer tudo. O amor tudo sustenta e tudo perdoa. O amor nos capacita a suportar os sofrimentos, as injustiças, e até as perseguições, transformando tudo em mérito para a vida eterna. Não existe amor sem sacrifício, nem sacrifício sem amor.';
            WHEN 3 THEN
                v_quote := '“Deus não pode estar em ti, porque já estás repleto de ti.”';
                v_meditation := 'O orgulho e a vaidade são o principal obstáculo ao conhecimento de Deus. O homem que se considera autossuficiente e dotado de toda a sabedoria não encontra lugar para Deus em seu coração. Deus, em sua infinita sabedoria, se revela aos pequenos e humildes, enquanto esconde seus mistérios dos arrogantes. Quantas pessoas, por se considerarem sábias, ignoram a verdade revelada por Deus? A humildade é a porta de entrada para a sabedoria divina. Não se pode alcançar a glória celestial sem o reconhecimento da própria limitação e a dependência da graça divina. Que esta novena nos ajude a esvaziar-nos de nós mesmos para que Deus possa nos preencher.';
            WHEN 4 THEN
                v_quote := '“Quem te criou sem ti, não te salvará sem ti.”';
                v_meditation := 'A graça de Deus é fundamental para a nossa salvação, mas a nossa colaboração é igualmente necessária. Deus nos deu o livre-arbítrio e espera que usemos nossa liberdade para escolher o bem e corresponder à sua graça. Não somos meros espectadores na nossa própria salvação, mas colaboradores de Deus. A fé sem obras é morta, assim como a oração sem esforço de nossa parte não trará frutos. A salvação é um dom gratuito de Deus, mas exige nossa resposta ativa e perseverante.';
            WHEN 5 THEN
                v_quote := '“Deus não nos ouve, ou por pedirmos mal, ou por pedirmos coisas ruins. Em latim: aut male, aut mala.”';
                v_meditation := 'Em sua sabedoria, Santo Agostinho nos lembra que a oração é um diálogo com Deus, e que nossa comunicação deve ser feita com pureza de intenção e discernimento. Muitas vezes, nossas preces não são atendidas porque pedimos coisas que não contribuem para a nossa salvação ou porque as pedimos de forma inadequada. Deus, em sua infinita bondade, sabe o que é melhor para nós e nos concede as graças que realmente precisamos, mesmo que não sejam as que esperamos. Devemos rezar com humildade, fé e perseverança, confiando na Providência divina. Não devemos nos desesperar se as coisas não acontecem como queremos, pois Deus tem um plano maior para nós.';
            WHEN 6 THEN
                v_quote := '“Dai-me a força de vos buscar, Vós que permitistes serdes encontrado e me cumulastes de esperança de vos encontrar sempre mais. Minha força e minha fraqueza estão diante de Vós, conservai a primeira, curai a segunda.”';
                v_meditation := 'Santo Agostinho nos mostra a profunda dependência do homem em relação a Deus. Reconhecer nossa fragilidade e fraqueza é o primeiro passo para nos abrirmos à graça divina. Somente com a força que vem de Deus podemos perseverar na fé, vencer as tentações e trilhar o caminho da santidade. A oração é o meio pelo qual buscamos essa força, e a certeza de que Deus nos ouvirá deve nos encher de esperança. Não é nossa própria força que nos levará ao Céu, mas a graça de Deus, que nos sustenta e nos cura.';
            WHEN 7 THEN
                v_quote := '“Estes são vossos servos, meus irmãos, que quisestes que fossem filhos vossos e meus senhores, a quem me ordenastes servir, se convosco quiser viver.”';
                v_meditation := '“Na oração afastemo-nos, portanto, do muito falar, mas não deixemos de muito suplicar, enquanto perseverar o fervor da intenção. Pois o muito falar é fazer uma coisa necessária com palavras supérfluas. Mas o muito suplicar é incitar-nos, por longos e piedosos desejos do coração, Àquele a quem rezamos. Geralmente, isso se faz mais com gemidos do que com discursos, mais com lágrimas do que com palavras.”';
            WHEN 8 THEN
                v_quote := '“Enquanto viveres é impossível que se perca o filho dessas lágrimas.”';
                v_meditation := 'Santo Agostinho finalmente recebeu o batismo na Páscoa de 387, e as lágrimas da piedosa mãe se transformaram em lágrimas de alegria. Algum tempo depois, quando chegaram juntos a Óstia com a intenção de retornarem à África, Mônica e seu filho conversavam sobre as promessas da vida eterna, e ela lhe disse: “Meu filho, quanto a mim, já nenhuma coisa me atrai nesta vida. O que farei e porque estou aqui, eu ignoro; já se consumiu minha esperança neste mundo. Só havia uma coisa que me fazia desejar continuar aqui um pouco mais: ver-te cristão católico antes de morrer. Meu Deus concedeu-me amplamente essa mercê, porque te vejo desprezar as felicidades terrenas para melhor servi-lo. Que estou a fazer aqui?”. Cinco dias depois, doente com febre, descansou no Senhor.';
            WHEN 9 THEN
                v_quote := '“Era a Vós que eu procurava. E Vós estáveis dentro da parte mais profunda e acima da parte mais alta do meu ser.”';
                v_meditation := '“Tarde vos amei, beleza tão antiga e tão nova, tarde vos amei! Eis que Vós estáveis dentro, e eu fora. Lá vos procurava. Deformado, lancei-me sobre as belas coisas que criastes. Vós estáveis comigo, e eu não estava convosco. Me mantiveram longe de Vós, essas coisas que, se não existissem em Vós, não existiriam.”';
        END CASE;

        -- Insert Content Blocks
        
        -- Block 0: Intro Prayer
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 0, 'prayer', 'Oração Inicial:\n\nPeregrino e enfermo, volto a Vós, Deus meu, cansado de peregrinar fora de Vós, e agoniado pelo grave peso de meus males. Vi, experimentei: fora de Vós não há abrigo, nem fartura, nem descanso, nem bem algum que sacie os desejos da alma que criastes.' || chr(10) || chr(10) || 'Pai-Nosso; Ave-Maria; Glória ao Pai.');

        -- Block 1: Litany
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 1, 'prayer', 'Ladainha de Santo Agostinho:\n\nSenhor, tende piedade de nós. Senhor, tende piedade de nós.\nCristo, tende piedade de nós. Cristo, tende piedade de nós.\nSenhor, tende piedade de nós. Senhor, tende piedade de nós.\nJesus Cristo, ouvi-nos. Jesus Cristo, ouvi-nos.\nJesus Cristo, atendei-nos. Jesus Cristo, atendei-nos.\nDeus, Pai do Céu, tende piedade de nós.\nFilho, Redentor do mundo, tende piedade de nós.\nDeus, Espírito Santo, tende piedade de nós.\nSantíssima Trindade, Único Deus, tende piedade de nós.\n\nSanta Maria, rogai por nós.\nSanta Mãe de Deus, rogai por nós.\nSanta Virgem das virgens, rogai por nós.\nSanto Agostinho, Doutor da Igreja, rogai por nós.\nSanto Agostinho, filho das lágrimas de Santa Mônica, rogai por nós.\nSanto Agostinho, luz dos que ensinam, rogai por nós.\nSanto Agostinho, debelador das heresias, rogai por nós.\nSanto Agostinho, ilustre guerreiro contra os erros, rogai por nós.\nSanto Agostinho, fonte inesgotável de eloquência cristã, rogai por nós.\nSanto Agostinho, brilhante espelho da santidade, rogai por nós.\nSanto Agostinho, modelo de todas as virtudes, rogai por nós.\n\nCordeiro de Deus, que tirais os pecados do mundo, perdoai-nos, Senhor.\nCordeiro de Deus, que tirais os pecados do mundo, ouvi-nos, Senhor.\nCordeiro de Deus, que tirais os pecados do mundo, tende piedade de nós.\nÓ Cristo, ouvi-nos! Ó Cristo, atendei-nos!');

        -- Block 2: Quote of the Day
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 2, 'quote', v_quote);

        -- Block 3: Meditation
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 3, 'paragraph', 'Meditação:\n\n' || v_meditation);

        -- Block 4: Final Prayer
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 4, 'prayer', 'Oração Final:\n\nÓ Deus, que iluminastes o vosso Bispo Santo Agostinho com a luz da vossa graça, para que ele buscasse ardorosamente a Vossa sabedoria e a encontrasse; iluminai também os nossos corações com a Vossa luz, para que sempre Vos procuremos e Vos amemos sobre todas as coisas. Por Cristo Nosso Senhor. Amém.');

         -- Block 5: Checklist Marker
        INSERT INTO day_content_blocks (novena_day_id, sort_order, block_type, content)
        VALUES (v_day_id, 5, 'checklist', 'Checklist do Dia');

        -- Insert Checklist Items
        INSERT INTO day_checklist_items (novena_day_id, label, repetition_count)
        VALUES (v_day_id, 'Rezar Pai-Nosso, Ave-Maria e Glória', 1);

    END LOOP;
END $$;



-- From 20251226152000_add_repetition_logic.sql
-- Migration: Add repetition_count to day_checklist_items and update St Joseph Novena

-- 1. Add repetition_count column
ALTER TABLE public.day_checklist_items 
ADD COLUMN repetition_count integer DEFAULT 1 NOT NULL;

-- 2. Update St Joseph Novena Data
DO $$
DECLARE
  v_novena_id uuid;
  v_day_record record;
BEGIN
  -- Get St Joseph Novena ID
  SELECT id INTO v_novena_id FROM public.novenas WHERE slug = 'novena-a-sao-jose';
  
  IF v_novena_id IS NOT NULL THEN
    -- Loop through all days of this novena
    FOR v_day_record IN SELECT id FROM public.novena_days WHERE novena_id = v_novena_id LOOP
      
      -- Remove the old single checklist item
      DELETE FROM public.day_checklist_items WHERE novena_day_id = v_day_record.id;

      -- Insert the 3 new interactive items
      INSERT INTO public.day_checklist_items (novena_day_id, label, label_pt, sort_order, repetition_count) VALUES
      (v_day_record.id, 'Our Father', 'Sete Pai-Nossos', 1, 7),
      (v_day_record.id, 'Hail Mary', 'Sete Ave-Marias', 2, 7),
      (v_day_record.id, 'Glory Be', 'Sete Glórias', 3, 7);
      
    END LOOP;
  END IF;
END $$;



-- From 20251226171500_robust_fix_sao_rafael.sql
-- Force correct ordering for Novena of São Rafael Arcanjo ROBUSTLY

DO $$ 
DECLARE
    v_novena_id uuid;
    v_day_record RECORD;
BEGIN
    -- Get Novena ID
    SELECT id INTO v_novena_id FROM novenas WHERE slug = 'sao-rafael-arcanjo';

    -- If found, proceed
    IF v_novena_id IS NOT NULL THEN
        -- Loop through all days of this novena
        FOR v_day_record IN SELECT id FROM novena_days WHERE novena_id = v_novena_id LOOP
            
            -- 0. Intro 
            UPDATE day_content_blocks SET sort_order = 0 
            WHERE novena_day_id = v_day_record.id AND content ILIKE '%Inicia-se%';

            -- 1. Bible 
            UPDATE day_content_blocks SET sort_order = 1 
            WHERE novena_day_id = v_day_record.id AND block_type = 'quote' AND content ILIKE '%Tobias%';

            -- 2. Opening Prayer
            UPDATE day_content_blocks SET sort_order = 2 
            WHERE novena_day_id = v_day_record.id AND content ILIKE '%efável bondade%';

            -- 3. Daily Prayer
            UPDATE day_content_blocks SET sort_order = 3 
            WHERE novena_day_id = v_day_record.id 
            AND content ILIKE '%indigno devoto%';

            -- 4. Intention
            UPDATE day_content_blocks SET sort_order = 4 
            WHERE novena_day_id = v_day_record.id AND block_type = 'intention';

            -- 5. Invocation
            UPDATE day_content_blocks SET sort_order = 5 
            WHERE novena_day_id = v_day_record.id AND content ILIKE '%Invocação%';

            -- 6. Checklist Marker (Type 'checklist')
            UPDATE day_content_blocks SET sort_order = 6 
            WHERE novena_day_id = v_day_record.id AND block_type = 'checklist';

            -- 7. Litany (Ladainha)
            UPDATE day_content_blocks SET sort_order = 7 
            WHERE novena_day_id = v_day_record.id AND content ILIKE '%Ladainha%';

            -- 8. Final Prayer (Oração Final)
            UPDATE day_content_blocks SET sort_order = 8 
            WHERE novena_day_id = v_day_record.id AND content ILIKE '%Oração Final%';

            -- 9. Footer
            UPDATE day_content_blocks SET sort_order = 9 
            WHERE novena_day_id = v_day_record.id AND content ILIKE '%Bendito%';

        END LOOP;
    END IF;
END $$;
